// 简化 SM-2：quality 0..5，返回 {intervalDays, repetitions, efactor, dueDate}
function reviewCard(card, quality, todayISO){
  var ef = card.efactor != null ? card.efactor : 2.5;
  var rep = card.repetitions || 0;
  var last = card.intervalDays || 0;
  if(quality < 3){
    rep = 0;
    var interval = 1;
  } else {
    rep += 1;
    if(rep === 1) interval = 1;
    else if(rep === 2) interval = 6;
    else interval = Math.round(last * ef);
  }
  ef = ef + (0.1 - (5-quality)*(0.08 + (5-quality)*0.02));
  if(ef < 1.3) ef = 1.3;
  var today = todayISO ? new Date(todayISO) : new Date();
  var due = new Date(today.getTime() + interval*86400000);
  return { intervalDays: interval, repetitions: rep, efactor: Math.round(ef*100)/100,
           dueDate: due.toISOString().slice(0,10) };
}
function nextDuePreview(card, todayISO){
  var out=[];
  var c = { efactor: card.efactor, repetitions: card.repetitions, intervalDays: card.intervalDays };
  for(var q=0;q<=5;q++){
    var r = reviewCard(c, q, todayISO);
    out.push({ quality:q, intervalDays:r.intervalDays, efactor:r.efactor });
  }
  return out;
}

var EXPORTS={reviewCard:reviewCard,nextDuePreview:nextDuePreview};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SpacedRepForgePure = EXPORTS; }
